(* LPS 727298f3: [drv_openat_toolong]'s 4096-byte name read is bounded by [TASK_SIZE]; with
   [4096 <= length path] it follows from [astr_at]'s bound on the path string. *)
Lemma task_of_astr : forall (R : bvmap 5 word) (p : Z) (n : nat) (s : word),
  getr R 11 = Z_to_bv 64 p -> (4096 <= n)%nat -> p + Z.of_nat n + 10 <= 0x800000000000 ->
  bv_unsigned s <= p -> bv_unsigned (getr R 11) + 4096 <= TASK_SIZE.
Proof.
  intros R p n s E Hn Hb Hs. pose proof (u64_range s) as Hr. rewrite E, Z_to_bv_unsigned.
  unfold bv_wrap, bv_modulus. change (2 ^ Z.of_N 64) with 18446744073709551616.
  rewrite Z.mod_small by lia. unfold TASK_SIZE. lia.
Qed.

