      (* The recorded [x_header] rewrites a [TSet] equation with [eq_ind_r]; the replay checks
         its term against the universe graph as it stands, which at the revision no longer
         holds the constraint [TSet <= eq_ind_r] that an earlier file used to add.  Elaborating
         this lemma adds it. *)
      Lemma tset_eq_ind_r : forall (x y : TSet) (P : TSet -> Prop), P x -> y = x -> P y.
      Proof. intros x y P Hx E. exact (@eq_ind_r TSet x P Hx y E). Qed.
      (* [comment removed for export] *)
      Lemma x_header : forall s msF mo regs mem p A cap,
        as_VIS H s msF = mkst regs (Z_to_bv 64 0x1a6628) mem rom -> as_AKREL H s (mkCfg msF mo) ->
        AXInv H sp0 pp tid can data (m_fs mo0) mem0 cap A s p regs mem mo ->
        realizes asegs (mkCfg msF mo) (t_body data (m_fs mo0)).
Proof.
