    (* [comment removed for export] *)
    Lemma open_fail : forall e R M msF' mo',
      In e openat_errnos \/ e = ENAMETOOLONG \/ e = ENOENT ->
      regs_ok E0 srA R -> know_ok RSEGS E0 M knA -> mstatics H sp0 tid can mem0 M ->
      as_VIS H s0 msF' = mkst (regupd R 10 (errno_ret e)) (Z_to_bv 64 0x1a6628) M rom -> as_AKREL H s0 (mkCfg msF' mo') ->
      m_fds mo' = m_fds mo0 ->
      (* LPS 727298f3: the tail writes the message to fd 2, which needs the launch's reader *)
      m_channel_reader mo' = true ->
